import{_ as i,K as t,a as l,c as r,ac as a,b as s,q as o}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"围棋：落子、气、提子与胜负计算","description":"用九路棋盘认识气、提子和打劫，再通过具体数字理解面积计分。","frontmatter":{"title":"围棋：落子、气、提子与胜负计算","description":"用九路棋盘认识气、提子和打劫，再通过具体数字理解面积计分。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"围棋入门","summary":"用九路棋盘认识气、提子和打劫，再通过具体数字理解面积计分。","status":"active","related":[{"title":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：眼、死活与简单对杀","link":"/life/personal/chess/weiqi/life-death","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：从布局到收官的一盘棋复盘","link":"/life/personal/chess/weiqi/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":false,"next":{"text":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections"}},"headers":[],"relativePath":"life/personal/chess/weiqi/rules.md","filePath":"life/personal/chess/weiqi/rules.md"}'),p={name:"life/personal/chess/weiqi/rules.md"},c={class:"chess-example"},d={class:"chess-figure"};function h(_,e,u,g,f,m){const n=t("ArticleImage");return l(),r("div",null,[e[1]||(e[1]=a('<h1 id="围棋-落子、气、提子与胜负计算" tabindex="-1">围棋：落子、气、提子与胜负计算 <a class="header-anchor" href="#围棋-落子、气、提子与胜负计算" aria-label="Permalink to &quot;围棋：落子、气、提子与胜负计算&quot;">​</a></h1><p>围棋不是谁吃的棋多谁就赢。你要让自己的活棋和围住的区域形成更大的有效范围。先用 9×9 棋盘练习，能顺利下完和计分后再换大棋盘。</p><h2 id="从空棋盘开始" tabindex="-1">从空棋盘开始 <a class="header-anchor" href="#从空棋盘开始" aria-label="Permalink to &quot;从空棋盘开始&quot;">​</a></h2><p>黑先白后，轮流在空交叉点放一颗子。落下后不移动；一串棋的气被全部占住才会被提走。本文横坐标 A～I 不跳过 I，纵坐标 1～9 从下向上；有些软件会跳过 I，摆例子时请使用本文标法。</p><p><code>.</code> 是空点，<code>X</code> 是黑子，<code>O</code> 是白子。只算上下左右的相邻关系，不算斜角。</p><h2 id="什么是气" tabindex="-1">什么是气 <a class="header-anchor" href="#什么是气" aria-label="Permalink to &quot;什么是气&quot;">​</a></h2>',6)),s("div",c,[s("div",d,[s("p",null,[o(n,{src:"/images/chess/weiqi-liberties.svg",alt:"一颗黑子 · 四口气。橙圈：A3、B2、B4、C3；只算正交相邻。"})])]),e[0]||(e[0]=a(`<div class="chess-explanation"><p>一颗子旁边相邻的空点叫气。上下左右连在一起的同色子是一串，共享气；重复的空点只数一次。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5  . . . . .</span></span>
<span class="line"><span>4  . . . . .</span></span>
<span class="line"><span>3  . X . . .</span></span>
<span class="line"><span>2  . . . . .</span></span>
<span class="line"><span>1  . . . . .</span></span>
<span class="line"><span>   A B C D E</span></span></code></pre></div><p>B3 黑子有 A3、C3、B2、B4 四口气。若 C3 再放黑子，这两子连成一串，共有 A3、B2、B4、D3、C2、C4 六口气，不是八口：两子的连接处不是空点。</p></div>`,1))]),e[2]||(e[2]=a('<h2 id="怎样提子" tabindex="-1">怎样提子 <a class="header-anchor" href="#怎样提子" aria-label="Permalink to &quot;怎样提子&quot;">​</a></h2><p>摆黑子 B2，白子 A2、B1、C2，其他点空着。黑子只剩 B3 一口气，叫“被打吃”。白方下一步若下 B3，黑子没有气，取走 B2。被提的是整串，不是任选一颗。</p><p>轮黑走时，黑可以从 B2 向 B3 延伸；但“连一颗就活”是错误口诀。必须重新数新串的气，并检查白方下一手能否继续打吃。</p><p>本文练习不允许不提对方棋却使自己无气的落子。若落子同时提走邻近敌子，应先提敌子，再判断自己的气。不是所有看起来被包住的空点都不能下。</p><h2 id="劫-不能马上把局面还原" tabindex="-1">劫：不能马上把局面还原 <a class="header-anchor" href="#劫-不能马上把局面还原" aria-label="Permalink to &quot;劫：不能马上把局面还原&quot;">​</a></h2><p>有些单子互吃会使双方无限来回。基本劫规则要求：不能立即回提而恢复刚才的全盘局面。先在别处走，对方应手后，才可能回提；复杂重复局面的限制依规则体系不同。</p><p>初学时不要把“过一手”理解成随便喊一声就能回提。对手可能不应你的别处威胁，直接把劫补掉。</p><h2 id="一盘棋怎样计分" tabindex="-1">一盘棋怎样计分 <a class="header-anchor" href="#一盘棋怎样计分" aria-label="Permalink to &quot;一盘棋怎样计分&quot;">​</a></h2><p>本文入门练习采用<strong>面积计分</strong> ：终局确认死活并移除死子后，数盘上的活子和只由一方围住的空点；中立空点不算任何一方。双方都认为无需再下时连续停着，但死活有争议要按约定规则继续解决，不能随意宣布对方整块死了。</p><p>例如九路棋盘共 81 点，已确认终局：黑有 24 颗活子、18 个围住的空点，合计 42；白有 23 颗活子、16 个空点，合计 39。无中立点，42＋39＝81。若本次约定白贴 6.5 点，白的比较分是 45.5，白胜 3.5 点。6.5 只是本例约定，不代表所有棋盘和赛事都这样贴。</p><p>吃掉的棋不要再额外加入面积分，否则重复计算。另一种常见的“数目”体系主要计算空点并处理俘子，不能拿那套数字直接套本例。中国规则中常见的“子”和“目”表述也不要不经换算就混加。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ol><li>A1 角上的孤子有几口气？<strong>两口：A2、B1。</strong> 棋盘外不算气。</li><li>斜放 B2、C3 的黑子是否一串？<strong>不是。</strong> 没有上下左右连接。</li><li>上面计分例里黑吃过 8 子，要在 42 上再加 8 吗？<strong>不要。</strong> 本例是面积计分。</li></ol><p>参考：<a href="https://www.britgo.org/intro/intro2.html" target="_blank" rel="noopener noreferrer">英国围棋协会入门规则</a>、<a href="https://www.usgo-archive.org/files/pdf/conciserules.pdf" target="_blank" rel="noopener noreferrer">AGA 简明规则</a>。坐标与计分数字为教学示例。</p>',14))])}const q=i(p,[["render",h]]);export{k as __pageData,q as default};
